"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["65176"],{80330(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.classificacao_protecao_obrigatoria","status":422,"titulo":"Classifica\xe7\xe3o de prote\xe7\xe3o de dados do fato \xe9 obrigat\xf3ria"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.classificacao_protecao_obrigatoria","requisitos":["UNI-REQ-0143","UNI-REQ-0205"],"oQueAconteceu":["Todo fato do cat\xe1logo declara a classifica\xe7\xe3o de prote\xe7\xe3o de dados, e a recusa de um fato sem ela \xe9 regra do UNI-REQ-0143. A `classificacaoProtecao` do cadastro (`POST /api/configuracao/admin/fatos-candidato`, `POST /api/configuracao/admin/fatos-candidato/derivados` ou `POST /api/configuracao/admin/fatos-candidato/agregados`) ou da altera\xe7\xe3o da defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`), inclusive a do fato de sistema, chegou vazia ou s\xf3 com espa\xe7os. O campo ausente do corpo \xe9 recusado antes, como erro de requisi\xe7\xe3o (400).","A recusa vem na lista `errors` da resposta, com `field` igual a `classificacaoProtecao`. Nada \xe9 gravado. Uma classifica\xe7\xe3o preenchida que n\xe3o \xe9 do vocabul\xe1rio recebe [a recusa de classifica\xe7\xe3o fora do vocabul\xe1rio](/erros/uniplus.configuracao.fato_candidato.classificacao_protecao_invalida)."],"comoResolver":["Informe a classifica\xe7\xe3o do fato: `PUBLICO`, `INTERNO`, `PESSOAL`, `IDENTIFICADOR` ou `SENSIVEL`, em mai\xfasculas. O tipo de dado limita a escolha: veja [a classifica\xe7\xe3o incompat\xedvel com o dom\xednio do fato](/erros/uniplus.configuracao.fato_candidato.classificacao_abaixo_do_minimo_do_dominio). A classifica\xe7\xe3o, a finalidade e a hip\xf3tese legal do tratamento s\xe3o aprovadas pela prote\xe7\xe3o de dados antes de o fato ser usado na configura\xe7\xe3o de um processo (UNI-REQ-0205)."],"ondeAparece":["Cadastro de um fato do cat\xe1logo (declarado, derivado ou resumo de grupo)","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);